onNotification(item) {
  // Don't notify about canceled events.
  if (item.status == "CANCELLED") {
    return;
  }
  // Don't notify if you declined this event invitation.
  if (
    (item instanceof lazy.CalEvent || item instanceof Ci.calIEvent) &&
    item.calendar instanceof Ci.calISchedulingSupport &&
    item.calendar.isInvitation(item) &&
    item.calendar.getInvitedAttendee(item)?.participationStatus == "DECLINED"
  ) {
    return;
  }

  const alert = new AlertNotification({
    name: item.id,
    // Don't add an icon on macOS, the app icon is already shown.
    imageURL: AppConstants.platform == "macosx" ? "" : "chrome://branding/content/icon48.png",
    title: item.title,
    text: item.getProperty("description"),
    textClickable: true,
  });
  const alertsService = Cc["@mozilla.org/alerts-service;1"].getService(Ci.nsIAlertsService);
  alertsService.showAlertWithCallbacks(alert, {
    QueryInterface: ChromeUtils.generateQI(["nsIAlertCallbacks"]),
    onAlertClick(_action) {
      cal.window.getCalendarWindow()?.openEventDialogForViewing(item);
    },
    onAlertFinished() {},
  });
},
